// Pega a primeira linha da planilha de temas sem status "ok"
const items = $input.all();
const cfg = $('Config').first().json;

let found = null, rowIndex = -1;
for (let i = 0; i < items.length; i++) {
  const it = items[i].json;
  const status = (it.status || it.Status || '').toString().trim().toLowerCase();
  if (status !== 'ok' && status !== 'done' && status !== 'publicado') {
    found = it;
    rowIndex = (it.row_number != null) ? it.row_number : (i + 2);
    break;
  }
}
if (!found) return []; // nada pendente — encerra

const tema = found['tema'] || found['Tema'] || '';
const categoria = (found['categoria'] || found['Categoria'] || 'Concursos').toString();
const foco = found['foco'] || found['Foco'] || '';
const palavraChave = (found['palavra_chave'] || found['Palavra-chave'] || tema).toString().toLowerCase();
if (!tema) throw new Error('Linha ' + rowIndex + ' sem tema. Colunas: ' + Object.keys(found).join(', '));

return [{ json: {
  tipo: 'tema',
  assunto: tema,
  categoria,
  foco,
  palavra_chave: palavraChave,
  contexto: `Tema escolhido da pauta: ${tema}. Público-alvo: ${categoria}. Ângulo desejado: ${foco || 'aula completa focada em prova'}.`,
  rowIndex,
  sheetsUrl: cfg.GOOGLE_SHEETS_URL,
  cfg: {
    wpUrl: cfg.WORDPRESS_URL,
    urlCurso: cfg.URL_CURSO_PADRAO,
    whatsapp: cfg.WHATSAPP,
    siteName: cfg.SITE_NAME,
    screenshotUrl: cfg.SCREENSHOT_URL,
    cloudinaryCloud: cfg.CLOUDINARY_CLOUD,
    cloudinaryPreset: cfg.CLOUDINARY_PRESET
  },
  systemPromptB64: cfg.SYSTEM_PROMPT_B64
}}];

// Junta os dois feeds, filtra últimas 36h + palavras de edital/abertura
const items = $input.all().map(i => i.json);
const cfg = $('Config Notícias').first().json;

const KEYWORDS = /edital|inscri[cç][oõ]es\s+abert|concurso\s+aberto|saiu|publicado|autorizado|banca\s+definida|vagas/i;
const now = Date.now();
const H36 = 36 * 60 * 60 * 1000;

const news = items.map(it => ({
  titulo: (it.title || '').trim(),
  link: it.link || '',
  data: it.isoDate || it.pubDate || '',
  resumo: (it.contentSnippet || it.content || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().substring(0, 400),
  categorias: Array.isArray(it.categories) ? it.categories.map(c => (typeof c === 'string' ? c : (c && c._) || '')).join(', ') : ''
})).filter(n => {
  if (!n.titulo || !n.link) return false;
  const t = n.data ? new Date(n.data).getTime() : 0;
  if (t && (now - t) > H36) return false;
  return KEYWORDS.test(n.titulo + ' ' + n.resumo);
});

// dedupe por título
const seen = new Set();
const unicas = news.filter(n => {
  const k = n.titulo.toLowerCase().replace(/[^a-z0-9]+/g, '');
  if (seen.has(k)) return false;
  seen.add(k); return true;
}).slice(0, 15);

if (unicas.length === 0) return []; // nenhuma notícia relevante hoje — encerra

return [{ json: {
  noticias: unicas,
  cfgRaw: cfg
}}];

// Monta chamada Claude para ESCOLHER a melhor notícia (edital + Direito Constitucional)
const d = $input.first().json;
const lista = d.noticias.map((n, i) =>
  `${i + 1}. ${n.titulo}\n   Link: ${n.link}\n   Data: ${n.data}\n   Resumo: ${n.resumo}\n   Categorias: ${n.categorias}`
).join('\n\n');

const prompt = `Você é o editor do blog de Adriane Fauth, professora de Direito Constitucional focada em concursos públicos, OAB e INSS.

Abaixo está a lista de notícias de concursos das últimas 36 horas. Escolha a ÚNICA notícia mais relevante para o público dela, priorizando nesta ordem:
1. Edital PUBLICADO de concurso cujo conteúdo programático muito provavelmente inclui Direito Constitucional (tribunais, carreiras jurídicas e policiais, INSS, fiscais, área administrativa federal/estadual, legislativo).
2. Concurso de grande porte autorizado ou com banca definida que cobrará Direito Constitucional.
3. Notícia relevante para quem estuda para OAB ou INSS.

IGNORE concursos puramente da área de saúde, engenharia ou professores de outras disciplinas, salvo se muito grandes e com constitucional no edital.

NOTÍCIAS:
${lista}

Responda APENAS com JSON válido, sem markdown:
{"indice": <número da notícia escolhida>, "orgao": "nome do órgão/concurso", "titulo_post": "título de post atraente e específico (60-70 chars) mencionando Direito Constitucional quando fizer sentido", "palavra_chave": "palavra-chave SEO em minúsculas sem acento (ex: concurso trf4 direito constitucional)", "justificativa": "1 frase", "tem_constitucional": true/false, "uf": "sigla de 2 letras do estado do concurso em minusculas (ex: pr, sp, ba); use \"nacional\" se for concurso federal/nacional (INSS, TRF, PF, CNU, Banco do Brasil, orgaos da Uniao) ou se abranger todo o pais; use null se nao der para identificar"}`;

return [{ json: {
  requestBody: {
    model: 'claude-haiku-4-5-20251001',
    max_tokens: 1000,
    temperature: 0.2,
    messages: [{ role: 'user', content: prompt }]
  },
  noticias: d.noticias,
  cfgRaw: d.cfgRaw
}}];

// Lê a escolha do Claude e monta o briefing tipo "noticia"
const resp = $input.first().json;
const prev = $('Montar Seleção').first().json;
const cfg = prev.cfgRaw;

let text = '';
if (resp.content && Array.isArray(resp.content)) {
  text = resp.content.filter(b => b.type === 'text').map(b => b.text).join('');
}
text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let escolha;
try { escolha = JSON.parse(text); }
catch (e) {
  const m = text.match(/\{[\s\S]*\}/);
  if (m) escolha = JSON.parse(m[0]);
  else throw new Error('Claude não retornou JSON válido na seleção: ' + text.substring(0, 300));
}

const idx = (escolha.indice || 1) - 1;
const noticia = prev.noticias[Math.max(0, Math.min(idx, prev.noticias.length - 1))];

// Normaliza a UF devolvida pelo Claude (sigla minuscula, 'nacional' ou null)
const ufBruta = (escolha.uf || '').toString().trim().toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const UFS_VALIDAS = ['ac','al','ap','am','ba','ce','df','es','go','ma','mt','ms','mg','pa','pb',
  'pr','pe','pi','rj','rn','rs','ro','rr','sc','sp','se','to','nacional'];
const uf = UFS_VALIDAS.includes(ufBruta) ? ufBruta : null;

return [{ json: {
  tipo: 'noticia',
  uf,
  assunto: escolha.titulo_post || noticia.titulo,
  categoria: 'Concursos',
  foco: escolha.justificativa || '',
  palavra_chave: (escolha.palavra_chave || noticia.titulo).toString().toLowerCase(),
  contexto: `Notícia-base escolhida: "${noticia.titulo}" (${noticia.link}, ${noticia.data}). Órgão: ${escolha.orgao || 'ver notícia'}. Resumo: ${noticia.resumo}. Direito Constitucional confirmado no interesse: ${escolha.tem_constitucional}.`,
  linkNoticia: noticia.link,
  rowIndex: null,
  sheetsUrl: null,
  cfg: {
    wpUrl: cfg.WORDPRESS_URL,
    urlCurso: cfg.URL_CURSO_PADRAO,
    whatsapp: cfg.WHATSAPP,
    siteName: cfg.SITE_NAME,
    screenshotUrl: cfg.SCREENSHOT_URL,
    cloudinaryCloud: cfg.CLOUDINARY_CLOUD,
    cloudinaryPreset: cfg.CLOUDINARY_PRESET
  },
  systemPromptB64: cfg.SYSTEM_PROMPT_B64
}}];

// Monta a pesquisa no Perplexity conforme o tipo (tema ou noticia)
const d = $input.first().json;

let userPrompt;
if (d.tipo === 'tema') {
  userPrompt = `Pesquise em profundidade o tema de Direito Constitucional/Previdenciário abaixo para um artigo de blog educacional voltado a candidatos de ${d.categoria} no Brasil.

TEMA: ${d.assunto}
ÂNGULO: ${d.foco || 'aula completa focada em prova'}

<LIMITACOES>
* NÃO invente números de súmulas, artigos, julgados ou estatísticas. Só use dados reais e verificáveis com fonte.
* Jurisprudência: apenas STF e STJ, com número do processo/tema e ano.
</LIMITACOES>

<INSTRUCOES>
1. Base normativa completa: artigos da CF/88 (com parágrafos e incisos relevantes), leis e emendas constitucionais aplicáveis, com a redação atual.
2. Jurisprudência: súmulas vinculantes, temas de repercussão geral e julgados recentes (2023-2026) do STF/STJ sobre o tema.
3. Como as bancas cobram: FCC, Cebraspe, FGV e Cesgranrio — estilo de cobrança, pegadinhas clássicas, exemplos de questões reais recentes (cite concurso e ano).
4. Para INSS: conexão com a prática previdenciária e a prova do concurso do INSS. Para OAB: como o tema aparece na 1ª fase e qual o recorte da FGV.
5. Dúvidas mais comuns de alunos sobre o tema (fóruns, YouTube, Reddit).

Retorne primeiro um dossiê em texto corrido e AO FINAL um JSON estruturado:
{
  "tema": "${d.assunto}",
  "area": "área dentro do Direito Constitucional",
  "palavra_chave": "${d.palavra_chave}",
  "base_legal": [{"dispositivo": "Art. X, CF/88", "resumo": "o que diz"}],
  "kpis": {
    "artigos_cf": "quantos artigos da CF envolvidos",
    "sumulas_julgados": "quantas súmulas/julgados-chave",
    "incidencia": "dado real de incidência em prova, com fonte, ou null",
    "tempo_estudo": "tempo médio recomendado de estudo do tema"
  },
  "incidencia_bancas": [{"banca": "FCC", "nivel": "alta/média/baixa", "como_cobra": "1-2 frases", "pegadinha": "exemplo real"}],
  "jurisprudencia": [{"titulo": "Súmula Vinculante X / Tema Y RG / ADI Z", "ano": "...", "descricao": "2-3 frases: o que decidiu e como cai em prova"}],
  "roteiro_estudo": [{"passo": "...", "descricao": "1 frase"}],
  "faq": [{"pergunta": "...", "resposta": "resposta completa com dado concreto"}],
  "contexto_tema": "3-4 parágrafos didáticos",
  "citacao_dispositivo": "transcrição literal do dispositivo constitucional central",
  "citacao_fonte": "Art. X, CF/88",
  "fontes_dados": ["lista de fontes"]
}
</INSTRUCOES>`;
} else {
  userPrompt = `Pesquise em profundidade o concurso público abaixo para um artigo de blog de Adriane Fauth, professora de Direito Constitucional.

CONCURSO/NOTÍCIA: ${d.assunto}
CONTEXTO DA NOTÍCIA: ${d.contexto}
${d.linkNoticia ? 'LINK DA NOTÍCIA ORIGINAL: ' + d.linkNoticia : ''}

<LIMITACOES>
* NÃO invente vagas, salários, datas ou conteúdo programático. Use o edital oficial e fontes confiáveis (site da banca, Diário Oficial, blogs especializados), sempre citando a fonte.
</LIMITACOES>

<INSTRUCOES>
1. Dados oficiais do concurso: órgão, banca, cargos, vagas (imediatas + CR), escolaridade, remuneração detalhada, taxa, cronograma completo (inscrições, prova, resultado).
2. Conteúdo programático de DIREITO CONSTITUCIONAL deste edital: liste os tópicos exatos, e o número de questões/peso da disciplina se disponível.
3. Distribuição das disciplinas na prova (número de questões por matéria).
4. Histórico da banca em Direito Constitucional: temas favoritos, estilo (literalidade vs jurisprudência), exemplos de questões de provas anteriores do mesmo órgão/banca.
5. Jurisprudência quente que essa banca vem cobrando (2023-2026), com números reais.
6. Estratégia de estudo realista no tempo até a prova.

Retorne primeiro um dossiê em texto corrido e AO FINAL um JSON estruturado:
{
  "concurso": "nome do concurso",
  "orgao": "órgão",
  "banca": "banca organizadora",
  "palavra_chave": "${d.palavra_chave}",
  "kpis": {
    "vagas": "total de vagas (fonte)",
    "salario": "remuneração inicial",
    "questoes_constitucional": "nº de questões de constitucional ou peso, se houver",
    "data_prova": "data da prova ou previsão"
  },
  "dados_edital": {"escolaridade": "...", "taxa": "...", "inscricoes": "período", "requisitos": "..."},
  "distribuicao_disciplinas": [{"disciplina": "...", "questoes": "nº", "destaque": true/false}],
  "topicos_constitucional": [{"topico": "...", "comentario": "como estudar / como a banca cobra"}],
  "jurisprudencia_banca": [{"titulo": "...", "ano": "...", "descricao": "2-3 frases"}],
  "cronograma_estudo": [{"fase": "Semanas 1-2", "descricao": "..."}],
  "faq": [{"pergunta": "...", "resposta": "resposta completa com dado do edital"}],
  "contexto": "3-4 parágrafos sobre o concurso e a importância do constitucional nele",
  "citacao_dispositivo": "trecho literal do edital sobre o conteúdo de constitucional, se disponível",
  "citacao_fonte": "Edital nº X/ano",
  "fontes_dados": ["lista de fontes com URLs"]
}
</INSTRUCOES>`;
}

return [{ json: {
  ...d,
  requestBody: {
    model: 'sonar-pro',
    messages: [
      { role: 'system', content: 'Você é um pesquisador jurídico meticuloso. Pesquise na web, cite fontes reais e nunca invente dados jurídicos. Responda em português do Brasil.' },
      { role: 'user', content: userPrompt }
    ],
    max_tokens: 8000,
    temperature: 0.2,
    search_recency_filter: d.tipo === 'noticia' ? 'month' : 'year'
  }
}}];

// Extrai dossiê + JSON estruturado da resposta do Perplexity
const response = $input.first().json;
const prev = $('Montar Perplexity').first().json;

const content = response.choices?.[0]?.message?.content || '';
const citations = response.citations || (response.search_results || []).map(s => s.url) || [];

let pesquisa = null;
let dossie = content;

// pega o maior bloco JSON da resposta
const jsonMatches = content.match(/\{[\s\S]*\}/g);
if (jsonMatches && jsonMatches.length > 0) {
  let best = jsonMatches[0];
  for (const m of jsonMatches) { if (m.length > best.length) best = m; }
  try {
    pesquisa = JSON.parse(best.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim());
    const idx = content.indexOf(best);
    if (idx > 0) dossie = content.substring(0, idx).trim();
  } catch (e) {
    try {
      const fb = content.indexOf('{');
      const lb = content.lastIndexOf('}');
      if (fb !== -1 && lb > fb) pesquisa = JSON.parse(content.substring(fb, lb + 1));
    } catch (e2) {}
  }
}

if (!pesquisa) pesquisa = {};
pesquisa.palavra_chave = pesquisa.palavra_chave || prev.palavra_chave;

return [{ json: {
  ...prev,
  requestBody: undefined,
  pesquisa,
  pesquisa_json: JSON.stringify(pesquisa, null, 2),
  dossie_completo: dossie,
  fontes: citations
}}];

// Monta a chamada do Claude que escreve o artigo
const d = $input.first().json;
const systemPrompt = Buffer.from(d.systemPromptB64, 'base64').toString('utf-8');

const waLink = 'https://wa.me/' + String(d.cfg.whatsapp).replace(/\D/g, '') +
  '?text=' + encodeURIComponent('Olá! Vim pelo artigo "' + d.assunto + '" do blog e quero saber mais sobre os cursos.');

const userMessage = `Gere o artigo HTML completo.

TIPO DE ARTIGO: ${d.tipo === 'tema' ? 'MODO TEMA (aula escrita)' : 'MODO NOTÍCIA (cobertura de concurso)'}
ASSUNTO: ${d.assunto}
PÚBLICO-ALVO: ${d.categoria}
PALAVRA-CHAVE FOCO (use exatamente): ${d.palavra_chave}
[URL_CURSO] = ${d.cfg.urlCurso}
[WA_LINK] = ${waLink}
[WHATSAPP] = ${d.cfg.whatsapp}

=== BRIEFING ===
${d.contexto}

=== DOSSIÊ DE PESQUISA COMPLETO ===
${d.dossie_completo}

=== DADOS ESTRUTURADOS ===
${d.pesquisa_json}

=== FONTES DA PESQUISA ===
${(d.fontes || []).join('\n')}

=== INSTRUÇÕES FINAIS DE SEO (obrigatórias) ===
1. A palavra-chave exata "${d.palavra_chave}" deve aparecer: no <h1>, no primeiro parágrafo do lead, em 2-3 títulos h2/h3, e 8-12 vezes no corpo (pode variar acentuação naturalmente).
2. O <h1> deve ser atraente e específico, com <em> no termo principal.
3. Todos os números, súmulas, artigos e datas devem vir EXCLUSIVAMENTE do dossiê acima. Se um dado não estiver no dossiê, não o afirme.
4. Datas e edições: hoje é ${new Date().toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' })}. Use no eyebrow do hero.
5. Lembre-se: saída começa em <body> e termina em </body>, sem CSS, apenas classes da lista fechada.`;

return [{ json: {
  ...d,
  requestBody: {
    model: 'claude-sonnet-4-5-20250929',
    max_tokens: 32000,
    temperature: 0.5,
    system: [{ type: 'text', text: systemPrompt, cache_control: { type: 'ephemeral' } }],
    messages: [{ role: 'user', content: userMessage }]
  }
}}];

// Limpa o HTML do Claude e monta o corpo do post WordPress (RANK MATH + rascunho)
const response = $input.first().json;
const prev = $('Montar Claude').first().json;

let html = '';
if (response.content && Array.isArray(response.content)) {
  html = response.content.filter(b => b.type === 'text').map(b => b.text).join('');
} else if (typeof response.content === 'string') {
  html = response.content;
}
html = html.replace(/```html\n?/g, '').replace(/```\n?/g, '').trim();

// Remove qualquer <style> gerado por engano (o CSS mora no tema WordPress)
html = html.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');
html = html.replace(/<button[^>]*nav__theme[^>]*>[\s\S]*?<\/button>/gi, '');
html = html.replace(/data-theme="[^"]*"/gi, '');
html = html.replace(/<script(?![^>]*ld\+json)[\s\S]*?<\/script>/gi, '');

let bodyContent = html;
const bodyMatch = html.match(/<body[^>]*>([\s\S]*)<\/body>/i);
if (bodyMatch) bodyContent = bodyMatch[1].trim();

let schemaBlocks = '';
const schemaMatches = bodyContent.match(/<script type="application\/ld\+json">[\s\S]*?<\/script>/gi);
if (schemaMatches) {
  schemaBlocks = schemaMatches.join('\n');
  for (const s of schemaMatches) bodyContent = bodyContent.replace(s, '');
}

let wpContent = `<!-- wp:html -->
${schemaBlocks}
<div class="page-wrap">
${bodyContent}
</div>
<!-- /wp:html -->`;

// === SEO RANK MATH ===
const normalizar = (s) => String(s).toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();

const assunto = prev.assunto || 'artigo';
const kwBase = normalizar(prev.palavra_chave || assunto);

// Descobre como a palavra-chave aparece ACENTUADA no texto do artigo.
// (o Rank Math compara literalmente: se a kw for sem acento e o texto tiver acento,
//  ele não reconhece as ocorrências e acusa densidade baixa)
const textoVisivel = bodyContent.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ');
let mapa = [], normalizado = '';
for (let i = 0; i < textoVisivel.length; i++) {
  const ch = textoVisivel[i].toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  for (let k = 0; k < ch.length; k++) { normalizado += ch[k]; mapa.push(i); }
}
let focusKw = kwBase;      // usada pelo Rank Math (minúscula, com acento)
let kwOriginal = kwBase;   // como aparece escrita no texto (mantém maiúsculas: CF, INSS, OAB)
const pos = normalizado.indexOf(kwBase);
if (pos !== -1) {
  const ini = mapa[pos];
  const fim = mapa[Math.min(pos + kwBase.length - 1, mapa.length - 1)] + 1;
  const trecho = textoVisivel.substring(ini, fim).trim();
  if (normalizar(trecho) === kwBase) {
    focusKw = trecho.toLowerCase();
    kwOriginal = trecho;
  }
}

const slug = kwBase
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '')
  .replace(/-?20\d{2}$/, '');

// título do post = h1 gerado pelo Claude (sem tags), fallback no assunto
let postTitle = assunto;
const h1m = bodyContent.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
if (h1m) postTitle = h1m[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();

// === TÍTULO SEO: começa com a palavra-chave e contém um número (o ano) ===
const ano = new Date().getFullYear();
const capitalizar = (s) => s.charAt(0).toUpperCase() + s.slice(1);
const kwTitulo = capitalizar(kwOriginal);

// complemento vem do que sobra do título do post depois da palavra-chave
let complemento = '';
const tituloNorm = normalizar(postTitle);
const idxKw = tituloNorm.indexOf(kwBase);
if (idxKw !== -1) {
  complemento = postTitle.substring(idxKw + kwBase.length)
    .replace(/^[\s:\-–—,|]+/, '').trim();
} else {
  // a palavra-chave não aparece literalmente no título: usar complemento padrão
  // (evita repetir palavras da própria kw e gerar título redundante)
  complemento = '';
}
complemento = complemento
  .replace(/\s*[—–]\s*.*$/, '')          // corta o que vem após travessão
  .replace(/^[\s:\-–—,|]+/, '')          // limpa pontuação inicial
  .replace(/^20\d{2}[\s:,-]*/, '')       // limpa ano solto no início
  .trim();
// se o complemento repetir a palavra-chave, ele não acrescenta nada
if (normalizar(complemento).includes(kwBase)) complemento = '';
// complemento curto: até 32 caracteres, terminando em palavra inteira
if (complemento.length > 32) {
  complemento = complemento.substring(0, 32).replace(/\s+\S*$/, '').trim();
}
const complementoTemAno = /20\d{2}/.test(complemento);

let seoTitle = complemento
  ? `${kwTitulo}: ${complemento}${complementoTemAno ? '' : ' ' + ano}`
  : (prev.tipo === 'noticia'
      ? `${kwTitulo}: o que muda em ${ano}`
      : `${kwTitulo}: guia completo ${ano}`);

// limite de 60 caracteres, preservando kw no início e o ano no fim
if (seoTitle.length > 60) {
  const sufixo = ` ${ano}`;
  const espaco = 60 - kwTitulo.length - 2 - sufixo.length;
  let comp = complemento.substring(0, Math.max(0, espaco));
  comp = comp.replace(/\s+\S*$/, '').trim();
