// subtítulo enxuto e em caixa baixa (estilo da arte)
if (subtitulo.length > 62) {
  const palavras = subtitulo.split(/\s+/);
  let acc = '';
  for (const p of palavras) { if ((acc + ' ' + p).trim().length > 58) break; acc = (acc + ' ' + p).trim(); }
  subtitulo = acc;
}
// minúscula inicial só quando NÃO é sigla (ex.: "BPC/LOAS", "CF/88" ficam como estão)
if (!/^[A-ZÀ-Ú]{2}/.test(subtitulo)) subtitulo = subtitulo.charAt(0).toLowerCase() + subtitulo.slice(1);

const tituloUP = titulo.toUpperCase();

// ── quebra o título em até 3 linhas equilibradas ──
const quebrar = (txt, maxLinhas) => {
  const palavras = txt.split(/\s+/).filter(Boolean);
  if (palavras.length <= 1) return palavras;
  let melhor = null;
  for (let linhas = 1; linhas <= maxLinhas; linhas++) {
    const alvo = Math.ceil(txt.length / linhas);
    const res = []; let atual = '';
    for (const p of palavras) {
      if (!atual) { atual = p; continue; }
      if ((atual + ' ' + p).length <= alvo + 4) atual += ' ' + p;
      else { res.push(atual); atual = p; }
    }
    if (atual) res.push(atual);
    if (res.length <= linhas) {
      const maxLen = Math.max(...res.map(l => l.length));
      if (!melhor || maxLen < melhor.maxLen) melhor = { linhas: res, maxLen };
      if (maxLen <= 18) break;
    }
  }
  return melhor ? melhor.linhas : [txt];
};

