  if (p.length <= maxPalavras) return p.join(' ');
  let corte = p.slice(0, maxPalavras);
  while (corte.length > 2 && STOPFIM.has(corte[corte.length-1].toLowerCase())) corte.pop();
  return corte.join(' ') + (reticencias ? '…' : '');
};

const quebrar = (txt, maxLinhas, alvoChars) => {
  const palavras = String(txt).split(/\s+/).filter(Boolean);
  let melhor = null;
  for (let L = 1; L <= maxLinhas; L++) {
    const alvo = Math.ceil(txt.length / L);
    const res = []; let atual = '';
    for (const p of palavras) {
      if (!atual) { atual = p; continue; }
      if ((atual+' '+p).length <= Math.max(alvo, alvoChars) + 3) atual += ' '+p;
      else { res.push(atual); atual = p; }
    }
    if (atual) res.push(atual);
    if (res.length <= L) {
      const m = Math.max(...res.map(x=>x.length));
      if (!melhor || m < melhor.m) melhor = { linhas: res, m };
    }
  }
  return melhor ? melhor.linhas : [String(txt)];
};

