function gerarSlides(roteiro, fotos, tipo) {
  const pick = (i) => fotos[((i % fotos.length) + fotos.length) % fotos.length];
  const seed = (String(roteiro.titulo_capa).length + (roteiro.pontos||[]).length) % fotos.length;
  const renders = [];

  if (tipo === 'noticia') {
    // NOTÍCIA: carrossel curto — manchete + até 2 pontos + CTA com a professora
    const pontos = (roteiro.pontos||[]).slice(0, 2);
    const total = pontos.length + 2;
    renders.push({ name:'slide_1_capa', html: slideCapaNews({ titulo: roteiro.titulo_capa, subtitulo: roteiro.subtitulo_capa }), width:1080, height:1350 });
    pontos.forEach((p, i) => {
      renders.push({ name:`slide_${i+2}_ponto`, html: slidePontoNews({ ...p, indice:i+1, total, totalPontos:pontos.length }), width:1080, height:1350 });
    });
    renders.push({ name:`slide_${total}_cta`, html: slideCtaNews({ titulo: roteiro.cta_titulo, texto: roteiro.cta_texto, fotoUrl: pick(seed) }), width:1080, height:1350 });
    renders.push({ name:'story', html: slideStoryNews({ titulo: roteiro.titulo_capa, subtitulo: roteiro.subtitulo_capa, fotoUrl: pick(seed+1) }), width:1080, height:1920 });
    return renders;
  }

  // MATÉRIA: carrossel completo no tema escuro (inalterado)
  const T = TEMA_ESCURO;
  const total = (roteiro.pontos||[]).length + 2;
  renders.push({ name:'slide_1_capa', html: slideCapa({ titulo: roteiro.titulo_capa, subtitulo: roteiro.subtitulo_capa, fotoUrl: pick(seed), tipo }, T), width:1080, height:1350 });
  (roteiro.pontos||[]).forEach((p, i) => {
    renders.push({ name:`slide_${i+2}_ponto`, html: slidePonto({ ...p, indice:i+1, total, totalPontos:(roteiro.pontos||[]).length, tipo }, T), width:1080, height:1350 });
  });
  renders.push({ name:`slide_${total}_cta`, html: slideCta({ titulo: roteiro.cta_titulo, texto: roteiro.cta_texto, fotoUrl: pick(seed+2), tipo }, T), width:1080, height:1350 });
  renders.push({ name:'story', html: slideStory({ titulo: roteiro.titulo_capa, subtitulo: roteiro.subtitulo_capa, fotoUrl: pick(seed+1), tipo }, T), width:1080, height:1920 });
  return renders;
}

// ── nó n8n: monta os renders ──
const d = $input.first().json;
const renders = gerarSlides(d.roteiro, d.cfg.FOTOS, d.tipo);
const slug = ('ig_' + d.postId + '_' + String(d.roteiro.titulo_capa).toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]+/g,'_')).substring(0, 40);
return [{ json: { ...d, renders, cloudinarySlug: slug } }];

// Junta as URLs das imagens hospedadas no WordPress (carrossel na ordem + story)
const medias = $input.all().map(i => i.json);
const meta = $('Separar Slides').all().map(i => i.json);
if (medias.length !== meta.length) {
  throw new Error(`Upload devolveu ${medias.length} mídias, esperava ${meta.length}`);
}
const porNome = {};
meta.forEach((m, i) => {
  const url = medias[i].source_url || (medias[i].guid && medias[i].guid.rendered);
  if (!url) throw new Error('Mídia sem source_url no índice ' + i);
  porNome[m.name] = url;
});
const carouselUrls = meta.filter(m => m.name !== 'story')
  .sort((a, b) => a.idx - b.idx).map(m => porNome[m.name]);
const storyUrl = porNome['story'];
const d = meta[0];
return [{ json: {
  cfg: d.cfg, postId: d.postId, tagsAtuais: d.tagsAtuais,
  titulo: d.titulo, link: d.link,
  carouselUrls, storyUrl,
  caption: (d.roteiro && d.roteiro.caption_carrossel) || ''
}}];

// Junta a pauta atual e prepara a pesquisa de tendências no Perplexity
const linhas = $input.all().map(i => i.json).filter(r => r && (r.tema || r.Tema));
const temas = linhas.map(r => ({
  tema: String(r.tema || r.Tema || '').trim(),
  categoria: String(r.categoria || r.Categoria || '').trim(),
  status: String(r.status || r.Status || '').trim().toLowerCase()
}));
const publicados = temas.filter(t => t.status === 'ok').length;
const pendentes = temas.length - publicados;

const listaTemas = temas.map(t => `- ${t.tema} [${t.categoria || 'Concursos'}]`).join('\n');

const prompt = `Você pesquisa pautas para o blog da professora Adriane Fauth (Direito Constitucional para concursos públicos, OAB e INSS — Brasil).

O blog já tem estes temas na pauta:
${listaTemas}

Pesquise e me traga um panorama ATUAL (últimas 4 semanas) com:
1. Concursos públicos federais e estaduais com edital publicado ou iminente que cobrem Direito Constitucional (banca, cargos, datas).
2. Novidades do INSS e da Seguridade Social relevantes para quem estuda (mudanças em benefícios, teses, reformas em tramitação).
3. Julgados recentes ou pendentes do STF com repercussão geral que caem em prova (tema, número, o que discute).
4. Mudanças legislativas ou ECs recentes/em tramitação que afetam Direito Constitucional.
5. Temas de Constitucional mais cobrados nos últimos editais da OAB/FGV.

Seja específico e factual, com nomes, números e datas. Não invente.`;

return [{ json: {
  temasAtuais: temas.map(t => t.tema),
  categorias: [...new Set(temas.map(t => t.categoria).filter(Boolean))],
  publicados, pendentes,
  requestBody: {
    model: 'sonar-pro',
    messages: [{ role: 'user', content: prompt }],
    max_tokens: 2500, temperature: 0.2
  }
}}];

// Combina a pesquisa com a pauta atual e pede 8 temas novos ao Claude
const prev = $('Montar Pesquisa Pauta').first().json;
const resp = $input.first().json;
const pesquisa = (((resp.choices || [])[0] || {}).message || {}).content || '';
if (!pesquisa) throw new Error('Perplexity não devolveu conteúdo');

const prompt = `Você monta a pauta do blog da professora Adriane Fauth (Direito Constitucional, concursos, INSS e OAB).

TEMAS QUE JÁ ESTÃO NA PAUTA (NÃO repita nem crie variações muito próximas):
${prev.temasAtuais.map(t => '- ' + t).join('\n')}

PESQUISA DE TENDÊNCIAS DESTA SEMANA:
${pesquisa}

Crie EXATAMENTE 8 temas NOVOS para artigos, seguindo estas regras:
- Relacionados ao perfil da pauta atual: Direito Constitucional aplicado a concursos, INSS/Seguridade e OAB.
- Aproveite a pesquisa: temas ligados a editais reais, julgados recentes e mudanças legislativas valem mais que temas genéricos.
- Misture as categorias: 3 Concursos, 3 INSS, 2 OAB (nesta ordem de prioridade se precisar ajustar).
- tema: título-base do artigo (frase nominal clara, sem dois-pontos duplos).
- categoria: exatamente "Concursos", "INSS" ou "OAB".
- foco: 1 frase com o ângulo que a pesquisa do artigo deve seguir (o que priorizar, comparar ou explicar).
- palavra_chave: 2 a 5 palavras, minúsculas, SEM acento, como alguém pesquisa no Google.
- Responda APENAS com JSON válido, sem markdown:
[{"tema":"...","categoria":"...","foco":"...","palavra_chave":"..."}, ... 8 itens]`;

return [{ json: {
  temasAtuais: prev.temasAtuais,
  requestBody: {
    model: 'claude-sonnet-4-5-20250929',
    max_tokens: 2000, temperature: 0.7,
    messages: [{ role: 'user', content: prompt }]
  }
}}];

// Valida os 8 temas, remove duplicatas e prepara as linhas novas
const prev = $('Montar Sugestões Pauta').first().json;
const resp = $input.first().json;
let texto = (((resp.content || [])[0] || {}).text || '').trim();
texto = texto.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
const ini = texto.indexOf('['), fim = texto.lastIndexOf(']');
if (ini === -1 || fim <= ini) throw new Error('Claude não devolveu um array JSON');
const sugestoes = JSON.parse(texto.substring(ini, fim + 1));

const norm = (s) => String(s || '').toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();

const existentes = new Set(prev.temasAtuais.map(norm));
const CATS = new Set(['Concursos', 'INSS', 'OAB']);
const vistos = new Set();
const linhas = [];
for (const s of sugestoes) {
  const tema = String(s.tema || '').trim();
  const chave = norm(tema);
  if (!tema || !chave) continue;
  if (existentes.has(chave) || vistos.has(chave)) continue;   // já na pauta ou repetido
  vistos.add(chave);
  linhas.push({ json: {
    tema,
    categoria: CATS.has(String(s.categoria).trim()) ? String(s.categoria).trim() : 'Concursos',
    foco: String(s.foco || '').trim(),
    palavra_chave: norm(s.palavra_chave || tema)
  }});
  if (linhas.length >= 8) break;
}
if (!linhas.length) return []; // nada novo — encerra em silêncio
return linhas;

// Monta a sequência de mensagens do WhatsApp (1 item = 1 mensagem, na ordem de envio)
const d = $input.first().json;
const cfg = d.cfg;
const base = `${cfg.WHATS_URL}/message`;
const inst = cfg.WHATS_INSTANCE;
const NUM = cfg.WHATS_NUMBER;
const total = d.carouselUrls.length;
const msgs = [];

msgs.push({ url: `${base}/sendText/${inst}`, body: { number: NUM,
  text: `🟡 *POST PRONTO PARA O INSTAGRAM*\n\n*${d.titulo}*\n${d.link}\n\nAbaixo: os ${total} slides do carrossel (na ordem), o story e a legenda para copiar.` } });

d.carouselUrls.forEach((u, i) => {
  msgs.push({ url: `${base}/sendMedia/${inst}`, body: { number: NUM,
    mediatype: 'image', mimetype: 'image/jpeg', media: u,
    fileName: `slide_${i+1}.jpg`, caption: `Carrossel — slide ${i+1} de ${total}` } });
});

msgs.push({ url: `${base}/sendMedia/${inst}`, body: { number: NUM,
  mediatype: 'image', mimetype: 'image/jpeg', media: d.storyUrl,
  fileName: 'story.jpg', caption: '📱 STORY (formato 9:16)' } });

if (d.caption) {
  msgs.push({ url: `${base}/sendText/${inst}`, body: { number: NUM,
    text: `📝 *Legenda* (toque e segure para copiar):\n\n${d.caption}` } });
}

return msgs.map((m, i) => ({ json: { ordem: i + 1, ...m } }));

// Um item por slide, carregando os metadados do post
const d = $input.first().json;
return d.renders.map((r, i) => ({ json: {
  idx: i, name: r.name, html: r.html,
  ehStory: r.name === 'story',
  postId: d.postId, cfg: d.cfg, tagsAtuais: d.tagsAtuais,
  titulo: d.titulo, link: d.link, roteiro: d.roteiro
}}));

// Todas as mensagens saíram: devolve os dados do post para marcar a tag ig-ok
const d = $('Preparar Publicação').first().json;
return [{ json: { ...d, enviadoWhatsApp: true, mensagens: $input.all().length } }];

// Converte o XML dos feeds em itens (mesmos campos do nó RSS: title, link, isoDate, contentSnippet, categories)
const decode = (s) => String(s || '')
  .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#0?39;/g, "'").replace(/&nbsp;/g, ' ');
const tag = (xml, t) => {
  const m = xml.match(new RegExp('<' + t + '(?:\\s[^>]*)?>([\\s\\S]*?)<\\/' + t + '>', 'i'));
  return m ? decode(m[1]).trim() : '';
};
const out = [];
for (const item of $input.all()) {
  const xml = typeof item.json.data === 'string' ? item.json.data : (item.json.body || '');
  if (!xml || xml.indexOf('<item') === -1) continue;
  const blocos = xml.split(/<item(?:\s[^>]*)?>/i).slice(1);
  for (const b of blocos) {
    const corpo = b.split(/<\/item>/i)[0];
    const pub = tag(corpo, 'pubDate');
    let iso = '';
    if (pub) { const d = new Date(pub); if (!isNaN(d)) iso = d.toISOString(); }
    const cats = [...corpo.matchAll(/<category(?:\s[^>]*)?>([\s\S]*?)<\/category>/gi)].map(m => decode(m[1]).trim());
    const desc = tag(corpo, 'description') || tag(corpo, 'content:encoded');
    out.push({ json: {
      title: tag(corpo, 'title'),
      link: tag(corpo, 'link') || (corpo.match(/<guid[^>]*>([^<]+)<\/guid>/i) || [,''])[1].trim(),
      pubDate: pub, isoDate: iso,
      contentSnippet: desc.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().substring(0, 600),
      categories: cats
    }});
  }
}
return out;
